import sys

def min_operations_to_equalize(s):
    n = len(s)
    if n == 1:
        return 0

    flips = 0
    for i in range(1, n):
        if s[i] != s[i - 1]:
            flips += 1

    compressions = len(s) - len(set(s))

    return min(flips // 2 + compressions, n - 1)

def main():
    import sys
    input = sys.stdin.read().splitlines()
    t = int(input[0])
    results = []
    index = 1
    for _ in range(t):
        s = input[index]
        result = min_operations_to_equalize(s)
        results.append(str(result))
        index += 1
    print("\n".join(results))

if __name__ == "__main__":
    main()
